import pandas as pd


def run(inputs: dict) -> dict:
    def find_key(d, name):
        if name in d:
            return name
        lname = name.lower()
        for k in d:
            if k.lower() == lname:
                return k
        raise KeyError(name)

    dim_key = find_key(inputs, 'DIM_MEMBER')
    stg_key = find_key(inputs, 'STG_MEMBER')

    dim = inputs[dim_key].copy()
    stg = inputs[stg_key].copy()

    # Work with a list of dict records so we can mutate "in place" the same
    # way the legacy procedure updates rows and appends new ones, while
    # preserving original row order for untouched rows.
    records = dim.to_dict('records')

    def clean(x):
        # COALESCE(x, '') then RTRIM (trailing spaces only)
        if x is None or (isinstance(x, float) and pd.isna(x)) or pd.isna(x):
            return ''
        return str(x).rstrip(' ')

    def sig(city, tier):
        return clean(city) + '|' + clean(tier)

    def is_true_current(flag):
        try:
            return int(flag) == 1
        except (TypeError, ValueError):
            return False

    def start_key(sd):
        if sd is None or (isinstance(sd, float) and pd.isna(sd)) or pd.isna(sd):
            return pd.Timestamp.min
        try:
            return pd.Timestamp(sd)
        except Exception:
            return pd.Timestamp.min

    # Process staged records in original order (at most one per member_id).
    for _, s in stg.iterrows():
        mid = s['member_id']

        candidates = [
            (idx, rec) for idx, rec in enumerate(records)
            if rec.get('member_id') == mid and is_true_current(rec.get('is_current'))
        ]

        if not candidates:
            c_idx = None
        else:
            # Tie-break among multiple "current" rows for same member:
            # prefer the latest eff_start_date, then earliest original
            # position, to deterministically pick a single "current" row.
            def sort_key(item):
                i, r = item
                sk = start_key(r.get('eff_start_date'))
                return (-sk.value, i)

            candidates.sort(key=sort_key)
            c_idx = candidates[0][0]

        if c_idx is None:
            records.append({
                'member_id': mid,
                'city': s['city'],
                'tier': s['tier'],
                'eff_start_date': s['update_date'],
                'eff_end_date': pd.NaT,
                'is_current': 1,
            })
        else:
            c = records[c_idx]
            if sig(s['city'], s['tier']) != sig(c.get('city'), c.get('tier')):
                records[c_idx]['eff_end_date'] = s['update_date']
                records[c_idx]['is_current'] = 0
                records.append({
                    'member_id': mid,
                    'city': s['city'],
                    'tier': s['tier'],
                    'eff_start_date': s['update_date'],
                    'eff_end_date': pd.NaT,
                    'is_current': 1,
                })
            # else: no-op, keep existing stored city/tier exactly as they were

    out_cols = ['member_id', 'city', 'tier', 'eff_start_date', 'eff_end_date', 'is_current']
    out = pd.DataFrame(records, columns=out_cols)

    return {'dim_member_out': out}
